    assert_eq!(candidate(vec![1,null,3,3,3], 3), vec![1]);
    assert_eq!(candidate(vec![1,null,3,2,2,null,4,2,null,2], 2), vec![1, None, 3, 2, None, None, 4]);
    assert_eq!(candidate(vec![1,2,3,4,5,6,7], 3), vec![1, 2, 3, 4, 5, 6, 7]);
    assert_eq!(candidate(vec![1,2,3,2,2,2,2], 2), vec![1, None, 3]);
    assert_eq!(candidate(vec![1,null,1,1,1,1,1,1], 1), None);
